 * Records the details of a new pet owner.
 *
 * @param ownerFieldsDto The pet owner (required)
 * @param idempotencyKey Optional client-supplied key that makes the create idempotent. When a request repeats with a key already seen, the originally created owner is returned with 200 instead of creating a duplicate. (optional)
 * @return The request repeated an already-seen Idempotency-Key; the originally created owner is returned instead of creating a duplicate. (status code 200)
 *         or The pet owner was successfully added. (status code 201)
 *         or Bad request. (status code 400)
 *         or Server error. (status code 500)
 */
@Operation(
    operationId = "addOwner",
    summary = "Adds a pet owner",
    description = "Records the details of a new pet owner.",
    tags = { "owners" },
    responses = {
        @ApiResponse(responseCode = "200", description = "The request repeated an already-seen Idempotency-Key; the originally created owner is returned instead of creating a duplicate.", content = {
            @Content(mediaType = "application/json", schema = @Schema(implementation = OwnerDto.class))
        }),
        @ApiResponse(responseCode = "201", description = "The pet owner was successfully added.", content = {
            @Content(mediaType = "application/json", schema = @Schema(implementation = OwnerDto.class))
        }),
        @ApiResponse(responseCode = "400", description = "Bad request.", content = {
            @Content(mediaType = "application/json", schema = @Schema(implementation = ProblemDetailDto.class))
        }),
        @ApiResponse(responseCode = "500", description = "Server error.", content = {
            @Content(mediaType = "application/json", schema = @Schema(implementation = ProblemDetailDto.class))
        })
    }
)
@RequestMapping(
    method = RequestMethod.POST,
    value = OwnersApi.PATH_ADD_OWNER,
    produces = { "application/json" },
    consumes = { "application/json" }
)
default ResponseEntity<OwnerDto> addOwner(
    @Parameter(name = "OwnerFieldsDto", description = "The pet owner", required = true) @Valid @RequestBody OwnerFieldsDto ownerFieldsDto,
    @Parameter(name = "Idempotency-Key", description = "Optional client-supplied key that makes the create idempotent. When a request repeats with a key already seen, the originally created owner is returned with 200 instead of creating a duplicate.", in = ParameterIn.HEADER) @RequestHeader(value = "Idempotency-Key", required = false) @Nullable String idempotencyKey
) {
    getRequest().ifPresent(request -> {
